from _h import *
DAY = 20

def passage(title, paras, explain, src=None):
    b = {"type": "passage", "title": title, "paras": paras, "explain": explain}
    if src: b["cite"] = "（" + src + "）"
    return b

def toi(id, q, opts, ans, explain):
    return mcq(id, q, opts, ans, explain)

def kaisetsu(n, lines):
    return {"type": "reveal", "label": "本の解説（別冊）：問題%s" % n,
            "children": [{"type": "items", "title": "解答・解説", "items": [{"t": x} for x in lines]}]}

def goi(imp):
    return items("{語|ご}いリスト", [("重要{語|ご}い：" + imp, "Key words in this passage.")])

